// og_png.ts — base64-encoded OG image (PNG, 1200x630).
//
// Twitter/Facebook strict og:image requires PNG/JPG/WEBP/GIF (no SVG).
// Generated by:
//   chromium --headless --window-size=1200,630 \
//     --default-background-color=00000000 \
//     --screenshot=og.png file:///og.svg
// then base64-encoded. ~300KB raw → ~400KB string → still well under
// Cloudflare's 1MB compressed worker size limit.

